from html import escape as e
from pathlib import Path
import hashlib

def revision(name):
 p=Path(__file__).resolve().parents[1]/name
 return hashlib.sha256(p.read_bytes()).hexdigest()[:10]

def img(src,alt='',cls='',prefix='',eager=False):
 return f'<img src="{prefix}{src}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">' if src else ''

def logo(prefix=''):
 return f'<a class="brand" href="{prefix}index.html" aria-label="Бодреев — главная"><span class="brand-emblem" aria-hidden="true">Б<span>✳</span></span><span class="wordmark">БОДРЕЕВ<span class="brand-sub">МАСТЕРСКАЯ ПИВОВАРЕНИЯ</span></span></a>'

def chrome(title,body,active='',prefix='',extra=''):
 nav=[('Наборы','index.html#assort','home'),('Рецепты','recipes.html','recipes'),('Знания','digest.html','digest'),('Сообщество','index.html#community','community')]
 links=''.join(f'<a href="{prefix}{u}" {"aria-current=page" if a==active else ""}>{t}</a>' for t,u,a in nav)
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="theme-color" content="#19241f"><meta name="description" content="Бодреев — мастерская домашнего пивоварения. Зерновые наборы, рецепты и знания для собственного вкуса. Концепция сайта, вариант 2."><title>{e(title)} — Бодреев / Мастерская</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}fonts.css?v={revision('fonts.css')}"><link rel="stylesheet" href="{prefix}styles.css?v={revision('styles.css')}"><link rel="stylesheet" href="{prefix}brand.css?v={revision('brand.css')}"><script src="{prefix}app.js?v={revision('app.js')}" defer></script><script src="{prefix}brand.js?v={revision('brand.js')}" defer></script>{extra}</head><body class="v2 {active}" id="top"><a class="skip" href="#main">К содержанию</a><div class="preview-bar"><span>КОНЦЕПЦИЯ 02</span> Тестовая версия BodreevShow <a href="https://bodreevshow.ru/" target="_blank" rel="noopener">Оригинал ↗</a></div><header class="header wrap">{logo(prefix)}<nav class="nav" id="navigation" aria-label="Основная навигация">{links}<a class="mobile-only" href="{prefix}merch.html">Мерч</a><a class="mobile-only" href="{prefix}random.html">Пивотрон</a></nav><div class="header-tools"><a class="saved-link" href="{prefix}recipes.html#saved" aria-label="Сохранённые рецепты">♡ <span data-saved-count>0</span></a><a class="header-contact" href="{prefix}index.html#start">С чего начать <span>↗</span></a></div><button class="menu-toggle" aria-label="Открыть меню" aria-controls="navigation" aria-expanded="false">Меню <span>☰</span></button></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-main"><div>{logo(prefix)}<p>Вода. Солод. Хмель.<br>И кое-что от себя.</p></div><div><p class="eyebrow">МАСТЕРСКАЯ</p><a href="{prefix}index.html#assort">Зерновые наборы</a><a href="{prefix}recipes.html">Рецепты</a><a href="{prefix}digest.html">База знаний</a><a href="{prefix}merch.html">Мерч</a><a href="{prefix}random.html">Пивотрон</a><a href="https://www.radiobells.com/" target="_blank" rel="noopener">Радио для варки ↗</a></div><div><p class="eyebrow">НА СВЯЗИ</p><a href="https://t.me/bodreevbrew" target="_blank" rel="noopener">Telegram ↗</a><a href="https://www.youtube.com/@BodreevShow" target="_blank" rel="noopener">YouTube ↗</a><a href="https://vk.ru/bodreevpivo" target="_blank" rel="noopener">ВКонтакте ↗</a><a href="https://boosty.to/bodreevbrew" target="_blank" rel="noopener">Boosty ↗</a></div><div class="footer-write"><span class="eyebrow">ЕСТЬ ИДЕЯ?</span><a href="mailto:zernabor@mail.ru">Обсудим<br>вашу варку ↗</a><span>zernabor@mail.ru</span></div></div><div class="wrap footer-bottom"><span>Материалы © BodreevShow · Концепция 02 / 2026</span><span>Сделано с интересом к процессу.</span><a href="#top">Наверх ↑</a></div></footer><dialog class="order-dialog" id="order-dialog" aria-labelledby="order-title"><button class="close-dialog" aria-label="Закрыть окно">×</button><p class="eyebrow">НАПИСАТЬ BODREEVSHOW</p><h2 id="order-title">Обсудим заказ</h2><p class="muted">Подготовим письмо. Вы отправите его из своей почтовой программы.</p><form id="order-form"><label>Что вас интересует<input name="product" id="order-product" readonly></label><div class="form-grid"><label>Ваше имя<input name="name" autocomplete="name" required maxlength="100"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="150"></label></div><label>Комментарий<textarea name="message" rows="3" maxlength="3000" placeholder="Количество, вопросы, пожелания"></textarea></label><button class="button" type="submit">Подготовить письмо <span>↗</span></button><p class="form-note">Это тестовая страница. Заявка не отправляется автоматически.</p></form></dialog><dialog class="reader-dialog" id="reader-dialog" aria-labelledby="reader-title"><button class="close-dialog" aria-label="Закрыть рецепт">×</button><div id="reader-content"></div></dialog><div class="toast" role="status" aria-live="polite"></div></body></html>'''

def product(p,i):
 category='stout' if 'стаут' in p['name'].lower() else 'discovery' if i in [4,7] else 'classic'
 label={'stout':'Стауты','classic':'Знакомые названия','discovery':'Новые открытия'}[category]
 price=f"{p['price']:,}".replace(',',' ')
 return f'''<article class="product-card" data-search="{e(p['name'].lower())}" data-category="{category}"><div class="product-image tone-{i%4}"><span class="kit-category">{label}</span>{img(p['image'],p['name'])}<span class="kit-volume">25 <small>ЛИТРОВ</small></span></div><div class="product-content"><div class="product-meta"><span>Зерновой набор</span><span>№ {i+1:02}</span></div><h3>{e(p['name'])}</h3><div class="product-bottom"><strong>{price} ₽</strong><button class="kit-select" data-order="{e(p['name'])}" aria-label="Выбрать набор {e(p['name'])}">Выбрать ↗</button></div><a class="kit-video" href="{e(p['video'])}" target="_blank" rel="noopener">▷ Посмотреть варку</a></div></article>'''

def homepage(D):
 articles=D['articles'];feature=articles[17]
 faq=[('Я ни разу не варил. С чего начать?','Посмотрите материал «Варим пиво из зерна» и определитесь с оборудованием. Наборы подходят начинающим при наличии минимального оборудования. Если остаются вопросы, напишите — обсудим вашу первую варку.'),('Набор — это готовое пиво?','Нет, это зерновой набор для домашнего пивоварения. Пиво вы варите самостоятельно. Состав конкретного набора и необходимое оборудование уточните перед заказом.'),('На какой объём рассчитан набор?','На 25 литров готового пива. Другой объём можно согласовать индивидуально.'),('Можно собрать набор под мой рецепт?','Да, на оригинальном сайте предусмотрены индивидуальные наборы по договорённости.'),('Как хранить набор?','В прохладном, сухом и тёмном месте.'),('Как заказать и уточнить доставку?','Выберите набор и подготовьте письмо. Наличие, состав, доставку и оплату согласуйте напрямую с BodreevShow. На тестовом сайте платежей нет.')]
 return f'''<section class="workshop-hero"><div class="hero-photo-bg">{img('assets/workshop-hero.webp','Авторская иллюстрация: солод, хмель и янтарное пиво на столе мастерской',eager=True)}</div><div class="wrap hero-layout"><div class="hero-brandline"><span class="small-star">✳</span> ДЛЯ ТЕХ, КТО ЛЮБИТ СОЗДАВАТЬ</div><h1>ПИВО<br>С ВАШИМ<br><span>ХАРАКТЕРОМ.</span></h1><div class="hero-lower"><p>Хорошее пиво начинается с любопытства.<br>Соберите свою варку — от первого<br>зерна до собственного рецепта.</p><div class="hero-actions"><a class="button button-orange" href="#assort">Выбрать набор <span>↗</span></a><a class="hero-start-link" href="#start">Я здесь впервые ↓</a></div></div><div class="hero-side-note"><span>ДОМАШНЕЕ ПИВОВАРЕНИЕ</span><span>BODREEVSHOW / МАСТЕРСКАЯ</span></div><div class="hero-stamp"><span>СВОБОДА</span><b>✳</b><span>ВАРИТЬ СВОЁ</span></div><div class="hero-footnote"><span>СОЛОД · ХМЕЛЬ · ЗНАНИЯ · ВАШ ОПЫТ</span><span>КОНЦЕПТ-ИЛЛЮСТРАЦИЯ</span></div></div></section><section class="brand-intro wrap"><p class="eyebrow">МАСТЕРСКАЯ БОДРЕЕВА</p><h2>От первой варки —<br><span>к собственному вкусу.</span></h2><div class="intro-bottom"><p>Наборы помогают начать. Рецепты — пробовать новое.<br>Знания превращают каждую варку в ваш собственный опыт.</p><a class="text-link" href="digest.html">Исследовать пивоварение ↗</a></div></section><section class="start-section" id="start"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">01 / ВАША ТОЧКА СТАРТА</p><h2>Каждому —<br>свой первый шаг.</h2></div><p class="section-note">Опыт не обязателен.<br>Интерес — отличное начало.</p></div><div class="start-grid"><a class="start-card" href="articles/{articles[2]['id']}.html"><span class="step-no">01</span><div class="path-symbol">↗</div><h3>Первая варка</h3><p>Разобраться в процессе и понять, с чего начать.</p><span class="path-link">К основам пивоварения ↗</span></a><a class="start-card" href="#assort" data-preset="classic"><span class="step-no">02</span><div class="path-symbol">≋</div><h3>Знакомый вкус</h3><p>Выбрать набор со знакомым названием и посмотреть варку.</p><span class="path-link">К зерновым наборам ↗</span></a><a class="start-card orange-card" href="#freedom"><span class="step-no">03</span><div class="path-symbol">✳</div><h3>Свой эксперимент</h3><p>Выйти за рамки готового рецепта и найти собственное сочетание.</p><span class="path-link">К «Коробке № 1» ↗</span></a></div></div></section><section class="catalog wrap section" id="assort"><div class="section-heading"><div><p class="eyebrow">02 / ИНГРЕДИЕНТЫ ДЛЯ ВАШЕЙ ИДЕИ</p><h2>Что будем<br><span class="serif-word">варить?</span></h2></div><p class="section-note">10 зерновых наборов.<br>Каждый рассчитан на 25 литров.</p></div><div class="catalog-toolbar"><div class="kit-filters" aria-label="Категории наборов"><button class="filter active" data-kit-filter="all" aria-pressed="true">Все <span>10</span></button><button class="filter" data-kit-filter="classic" aria-pressed="false">Знакомые названия</button><button class="filter" data-kit-filter="stout" aria-pressed="false">Стауты</button><button class="filter" data-kit-filter="discovery" aria-pressed="false">Открытия</button></div><label class="search"><span>⌕</span><input type="search" data-search-target=".product-card" placeholder="Поиск набора" aria-label="Поиск набора"></label></div><p class="results-caption" id="kit-results" role="status">Показано 10 наборов</p><div class="product-grid">{''.join(product(p,i) for i,p in enumerate(D['products']))}</div><p class="empty-state" hidden>Такого названия нет. Попробуйте другой запрос или категорию.</p><div class="catalog-help"><span>Пока не определились?</span><button class="text-link" data-order="Помогите выбрать набор для моей варки">Обсудить выбор с BodreevShow ↗</button></div></section><section class="freedom-section" id="freedom"><div class="wrap freedom-grid"><div class="freedom-copy"><p class="eyebrow">КОРОБКА № 1 / СВОБОДА ЭКСПЕРИМЕНТА</p><h2>Рецепт?<br><span>Ваш.</span></h2><p>В этой коробке есть ингредиенты и инструкция-направление. Каким станет пиво — лёгким или крепким, горьким или ароматным — решаете вы.</p><div class="freedom-price"><strong>3 000 ₽</strong><span>на 25 литров</span></div><button class="button button-orange" data-order="Коробка № 1">Начать эксперимент <span>↗</span></button></div><div class="freedom-art"><span class="freedom-outline">СВОЁ</span>{img(D['box'],'Оригинальный зерновой набор Коробка номер один')}<span class="art-caption">ОДИН НАБОР. РАЗНЫЕ ИСТОРИИ.</span></div></div></section><section class="wrap section knowledge"><div class="section-heading"><div><p class="eyebrow">03 / ЗНАНИЯ, КОТОРЫЕ ОСТАЮТСЯ С ВАМИ</p><h2>За вкусом<br>стоит <span class="serif-word">понимание.</span></h2></div><a class="text-link" href="digest.html">Вся база знаний ↗</a></div><div class="knowledge-grid"><a class="knowledge-feature" href="articles/{feature['id']}.html">{img(feature['image'],feature['name'])}<div><p class="eyebrow">ИНГРЕДИЕНТЫ / ХМЕЛЬ</p><h3>Маленькая шишка.<br>Большой характер.</h3><span>Разобраться в хмеле ↗</span></div></a><div class="reading-path"><p class="eyebrow">ПРОЧИТАТЬ ПЕРЕД ПЕРВОЙ ВАРКОЙ</p>{''.join(f'<a href="articles/{articles[i]["id"]}.html"><span>0{j+1}</span><div><h3>{e(articles[i]["name"])}</h3><p>{desc}</p></div><b>↗</b></a>' for j,(i,desc) in enumerate([(2,'Весь процесс — по порядку'),(3,'Основа вашей будущей варки'),(16,'Что происходит после кипячения')]))}<a class="all-recipes" href="recipes.html"><span>35</span><div><h3>Рецептов в библиотеке</h3><p>Сохраняйте и возвращайтесь к ним перед варкой</p></div><b>↗</b></a></div></div></section><section class="community-section" id="community"><div class="wrap community-grid"><div class="community-big">ВАРИМ.<br>ПРОБУЕМ.<br><span>ДЕЛИМСЯ.</span></div><div class="community-copy"><p class="eyebrow">BODREEVSHOW / СООБЩЕСТВО</p><h2>Увлечение,<br>которое объединяет.</h2><p>Смотрите варки на YouTube, следите за обновлениями в Telegram и делитесь своими рецептами. Хорошим идеям нужна компания.</p><div class="community-links"><a href="https://www.youtube.com/@BodreevShow" target="_blank" rel="noopener">YouTube <span>↗</span></a><a href="https://t.me/bodreevbrew" target="_blank" rel="noopener">Telegram <span>↗</span></a></div><a class="text-link" href="merch.html">Мерч Гильдии пивоваров ↗</a></div></div></section><section class="faq-section wrap section" id="faq"><div><p class="eyebrow">04 / БЕЗ ЛИШНИХ СЛОЖНОСТЕЙ</p><h2>До первого<br>кипячения.</h2><p class="muted">Ответы на вопросы, с которых<br>обычно начинается пивоварение.</p></div><div class="faq-list">{''.join(f'<details><summary><span>{q}</span><b>+</b></summary><p>{a}</p></details>' for q,a in faq)}</div></section><section class="final-contact wrap" id="form"><span class="eyebrow">СЛЕДУЮЩАЯ ВАРКА — ВАША</span><h2>Начнём с идеи?</h2><button class="button" data-order="Хочу обсудить свою следующую варку">Написать BodreevShow <span>↗</span></button><a href="mailto:zernabor@mail.ru">zernabor@mail.ru</a></section>'''

def recipespage(D,templates):
 cards=''
 for i,p in enumerate(D['recipes']):
  rid='recipe-'+p['id']
  cards+=f'''<article class="recipe-card" data-id="{rid}" data-search="{e(p['name'].lower())}" data-new="{str(p['new']).lower()}"><div class="recipe-image"><button class="recipe-open-image" data-recipe="{rid}" aria-label="Открыть рецепт {e(p['name'])}">{img(p['image'],p['name'])}</button><span class="recipe-badge">{'НОВИНКА' if p['new'] else 'РЕЦЕПТ'}</span><button class="save-recipe" data-save-recipe="{rid}" aria-label="Сохранить рецепт {e(p['name'])}" aria-pressed="false">♡</button></div><div class="recipe-card-copy"><span class="card-index">{i+1:02} / BODREEVSHOW</span><h3><button data-recipe="{rid}">{e(p['name'])}</button></h3><button class="text-link" data-recipe="{rid}">Читать рецепт ↗</button></div></article>'''
 return f'''<section class="page-hero wrap"><p class="eyebrow">БИБЛИОТЕКА / 35 РЕЦЕПТОВ</p><h1>Следующая варка.<br><em>Новая история.</em></h1><p>Сохраняйте понравившиеся рецепты, возвращайтесь к ним перед варкой и находите свои сочетания.</p></section><section class="wrap section page-content" id="saved"><div class="catalog-toolbar"><div class="filter-group" aria-label="Фильтр рецептов"><button class="filter active" data-filter="all" aria-pressed="true">Все рецепты <span>35</span></button><button class="filter" data-filter="new" aria-pressed="false">Новинки</button><button class="filter" data-filter="saved" aria-pressed="false">Сохранённые <span data-saved-count>0</span></button></div><label class="search"><span>⌕</span><input type="search" data-search-target=".recipe-card" placeholder="Название рецепта" aria-label="Поиск рецепта"></label></div><p class="saved-hint">Сохранённые рецепты остаются в этом браузере. Нажмите ♡ на карточке.</p><div class="recipe-grid">{cards}</div><p class="empty-state" hidden>Пока пусто. Измените поиск или сохраните рецепт, нажав ♡.</p><div class="share-recipe"><div><p class="eyebrow">ОПЫТОМ ХОЧЕТСЯ ДЕЛИТЬСЯ</p><h2>А какой рецепт ваш?</h2><p>Расскажите о своей варке: ингредиентах, процессе и результате.</p></div><button class="button" data-order="Хочу поделиться авторским рецептом">Поделиться рецептом ↗</button></div></section>{templates}'''
